// Distributes leftover space by flex-grow, like a flex container does
function distributeSpace(containerWidth, items) {
  const baseTotal = items.reduce((sum, item) => sum + item.base, 0);
  const growTotal = items.reduce((sum, item) => sum + item.grow, 0);
  const remaining = containerWidth - baseTotal;
  return items.map((item) => item.base + (remaining * item.grow) / growTotal);
}
console.log(distributeSpace(300, [{ base: 50, grow: 1 }, { base: 50, grow: 3 }]).join(","));

