// With flex-wrap, how many rows do the items need?
function rowsNeeded(itemWidth, containerWidth, itemCount) {
  const perRow = Math.floor(containerWidth / itemWidth);
  return Math.ceil(itemCount / perRow);
}
console.log(rowsNeeded(120, 500, 9));

